<script setup>
import { updateQuiz as wayfinderUpdateQuiz1, storeAssignment as wayfinderStoreAssignment2, storeQuiz as wayfinderStoreQuiz3, updateAssignment as wayfinderUpdateAssignment4 } from './../../../actions/App/Http/Controllers/Staff/AdminAssessmentController';

import { Link, router, useForm } from '@inertiajs/vue3';
import { computed, reactive } from 'vue';
import StaffAdminLayout from '../../../Layouts/StaffAdminLayout.vue';

const props = defineProps({ courses: Array, assignments: Object, quizzes: Object });
const assignment = useForm({ course_id: '', lesson_id: '', title: '', instructions: '', due_at: '', max_points: 100 });
const quiz = useForm({ course_id: '', lesson_id: '', title: '', pass_percent: 70, attempt_limit: 3, published: false, questions: [{ prompt: '', options: ['', '', '', ''], answer: 0 }] });
const lessonOptions = (courseId) => props.courses.find((course) => Number(course.id) === Number(courseId))?.modules.flatMap((module) => module.lessons.map((lesson) => ({ ...lesson, moduleTitle: module.title }))) || [];
const assignmentLessons = computed(() => lessonOptions(assignment.course_id));
const quizLessons = computed(() => lessonOptions(quiz.course_id));
const assignmentEdits = reactive(Object.fromEntries(props.assignments.data.map((item) => [item.id, { title: item.title, instructions: item.instructions, due_at: item.due_at ? item.due_at.slice(0,16) : '', max_points: item.max_points }])));
function addQuestion() { quiz.questions.push({ prompt: '', options: ['', '', '', ''], answer: 0 }); }
function addOption(question) { if (question.options.length < 8) question.options.push(''); }
function removeOption(question, index) { if (question.options.length > 2) question.options.splice(index, 1); if (question.answer >= question.options.length) question.answer = 0; }
function updateQuizStatus(item, published) { router.patch(wayfinderUpdateQuiz1.url({ quizId: item.id }), { published }, { preserveScroll: true }); }
</script>

<template><StaffAdminLayout><div class="admin-heading"><div><div class="eyebrow">COURSEWORK & CHECKPOINTS</div><h1>Assignments & quizzes.</h1><p>Prepare the work that supports live learning. Quiz answer keys are stored server-side and never sent to learners before submission.</p></div></div>
  <div class="assessment-forms"><section class="admin-panel"><h2>Create an assignment</h2><form class="admin-form" @submit.prevent="assignment.post(wayfinderStoreAssignment2().url)"><label>Course<select v-model="assignment.course_id" required><option value="">Select course</option><option v-for="item in courses" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label>Related lesson <small>(optional)</small><select v-model="assignment.lesson_id"><option value="">Course-level assignment</option><option v-for="lesson in assignmentLessons" :key="lesson.id" :value="lesson.id">{{ lesson.moduleTitle }} · {{ lesson.title }}</option></select></label><label>Title<input v-model="assignment.title" required></label><label>Instructions<textarea v-model="assignment.instructions" rows="6" required></textarea></label><div class="admin-form-grid"><label>Due date<input v-model="assignment.due_at" type="datetime-local"></label><label>Maximum points<input v-model.number="assignment.max_points" type="number" min="1"></label></div><div class="admin-form-actions"><button class="button button-dark" :disabled="assignment.processing">Create assignment</button></div></form></section>
    <section class="admin-panel"><h2>Create a quiz</h2><form class="admin-form" @submit.prevent="quiz.post(wayfinderStoreQuiz3().url)"><label>Course<select v-model="quiz.course_id" required><option value="">Select course</option><option v-for="item in courses" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label>Related lesson <small>(optional)</small><select v-model="quiz.lesson_id"><option value="">Course-level quiz</option><option v-for="lesson in quizLessons" :key="lesson.id" :value="lesson.id">{{ lesson.moduleTitle }} · {{ lesson.title }}</option></select></label><label>Title<input v-model="quiz.title" required></label><div class="admin-form-grid"><label>Pass percentage<input v-model.number="quiz.pass_percent" type="number" min="1" max="100"></label><label>Attempt limit<input v-model.number="quiz.attempt_limit" type="number" min="1" max="100"></label></div><article v-for="(question,index) in quiz.questions" :key="index" class="quiz-question-editor"><div class="question-editor-head"><b>Question {{ index+1 }}</b><button v-if="quiz.questions.length>1" type="button" class="admin-danger" @click="quiz.questions.splice(index,1)">Remove</button></div><label>Prompt<textarea v-model="question.prompt" rows="2" required></textarea></label><div v-for="(option,optionIndex) in question.options" :key="optionIndex" class="quiz-option-editor"><input type="radio" :name="`correct-${index}`" :value="optionIndex" v-model="question.answer" :aria-label="`Option ${optionIndex+1} is correct`"><input v-model="question.options[optionIndex]" :aria-label="`Option ${optionIndex+1}`" :placeholder="`Answer option ${optionIndex+1}`" required><button v-if="question.options.length>2" type="button" class="admin-danger" @click="removeOption(question,optionIndex)">×</button></div><button v-if="question.options.length<8" type="button" class="admin-secondary" @click="addOption(question)">+ Add answer choice</button></article><button type="button" class="admin-secondary" @click="addQuestion">+ Add question</button><label class="publish-checkbox"><input v-model="quiz.published" type="checkbox"> Publish quiz when saved</label><div class="admin-form-actions"><button class="button button-dark" :disabled="quiz.processing">Create quiz</button></div></form></section></div>
  <section class="admin-panel"><h2>Assignments</h2><details v-for="item in assignments.data" :key="item.id" class="assessment-record"><summary><span><b>{{ item.title }}</b><small>{{ item.course_title }}<template v-if="item.lesson_title"> · {{ item.lesson_title }}</template> · {{ item.max_points }} points</small></span><UiIcon name="arrow-up-right" :size="13"/></summary><form class="admin-form assessment-edit" @submit.prevent="router.put(wayfinderUpdateAssignment4.url({ assignmentId: item.id }), assignmentEdits[item.id], { preserveScroll: true })"><label>Title<input v-model="assignmentEdits[item.id].title" required></label><label>Instructions<textarea v-model="assignmentEdits[item.id].instructions" rows="4" required></textarea></label><div class="admin-form-grid"><label>Due date<input v-model="assignmentEdits[item.id].due_at" type="datetime-local"></label><label>Maximum points<input v-model.number="assignmentEdits[item.id].max_points" type="number" min="1"></label></div><div class="admin-form-actions"><button class="button button-dark">Save assignment</button></div></form></details><div v-if="assignments.last_page > 1" class="admin-pagination"><span>Page {{ assignments.current_page }} of {{ assignments.last_page }} · {{ assignments.total }} assignments</span><div><Link v-if="assignments.prev_page_url" :href="assignments.prev_page_url">Previous</Link><Link v-if="assignments.next_page_url" :href="assignments.next_page_url">Next</Link></div></div><div v-if="!assignments.data.length" class="admin-empty">No assignments have been created.</div></section>
  <section class="admin-panel"><h2>Quizzes</h2><div v-for="item in quizzes.data" :key="item.id" class="quiz-list-row"><span><b>{{ item.title }}</b><small>{{ item.course_title }} · {{ item.questions_count }} questions · {{ item.pass_percent }}% to pass</small></span><label><input type="checkbox" :checked="item.published" @change="updateQuizStatus(item,$event.target.checked)"> {{ item.published ? 'Published' : 'Draft' }}</label></div><div v-if="quizzes.last_page > 1" class="admin-pagination"><span>Page {{ quizzes.current_page }} of {{ quizzes.last_page }} · {{ quizzes.total }} quizzes</span><div><Link v-if="quizzes.prev_page_url" :href="quizzes.prev_page_url">Previous</Link><Link v-if="quizzes.next_page_url" :href="quizzes.next_page_url">Next</Link></div></div><div v-if="!quizzes.data.length" class="admin-empty">No quizzes have been created.</div></section>
</StaffAdminLayout></template>

<style scoped>.assessment-forms{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}.assessment-forms>.admin-panel{margin:0}.quiz-question-editor{border:1px solid #e9e8e2;border-radius:8px;padding:13px;margin-top:7px}.question-editor-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;font-size:12px}.quiz-option-editor{display:flex;gap:8px;align-items:center;margin:7px 0}.quiz-option-editor input[type=radio]{accent-color:#526b4a}.quiz-option-editor input:not([type=radio]){flex:1;padding:9px;border:1px solid #e2e1da;border-radius:6px}.admin-secondary{border:0;background:#edf0e9;color:#4e6446;border-radius:6px;padding:8px 11px;cursor:pointer;font-size:11px}.admin-danger{border:0;background:none;color:#a14c43;cursor:pointer}.publish-checkbox{display:flex!important;align-items:center;gap:8px!important}.assessment-record{border-top:1px solid #efeee9}.assessment-record summary{display:flex;justify-content:space-between;gap:12px;padding:14px 0;cursor:pointer;list-style:none}.assessment-record summary span,.quiz-list-row>span{display:grid;gap:5px}.assessment-record summary small,.quiz-list-row small{color:#7a8177}.assessment-edit{padding:4px 0 16px}.quiz-list-row{border-top:1px solid #efeee9;padding:14px 0;display:flex;justify-content:space-between;align-items:center;gap:15px}.quiz-list-row label{display:flex;align-items:center;gap:6px;font-size:11px;color:#616a5c}.quiz-list-row input{accent-color:#526b4a}@media(max-width:950px){.assessment-forms{grid-template-columns:1fr}}</style>

